CREATE DATABASE IF NOT EXISTS medcare_hospital CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE medcare_hospital;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('patient','doctor','hospital','admin') NOT NULL DEFAULT 'patient',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE hospitals(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,name VARCHAR(180) NOT NULL,address VARCHAR(255),city VARCHAR(100) NOT NULL,latitude DECIMAL(10,7),longitude DECIMAL(10,7),active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE doctors(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,hospital_id INT NOT NULL,specialty VARCHAR(120) NOT NULL,consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(hospital_id) REFERENCES hospitals(id)) ENGINE=InnoDB;
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,reason VARCHAR(500),status ENUM('pending','confirmed','completed','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES users(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id),INDEX idx_doctor_slot(doctor_id,appointment_date,appointment_time,status)) ENGINE=InnoDB;
CREATE TABLE checkins(id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT NOT NULL,patient_id INT NOT NULL,notes VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(id),FOREIGN KEY(patient_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE reviews(id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT NOT NULL UNIQUE,doctor_id INT NOT NULL,patient_id INT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(patient_id) REFERENCES users(id)) ENGINE=InnoDB;
